def digest(data):
    return hashlib.sha256(data.replace(b"\r\n", b"\n")).hexdigest()

def safe_path(root, name):
    relative = PurePosixPath(name)
    if relative.is_absolute() or ".." in relative.parts or not relative.parts or relative.parts[0] not in ("apps", "templates", "static"):
        raise ValueError("Unsafe path: " + name)
    path = root
    for part in relative.parts:
        path = path / part
        if path.is_symlink():
            raise ValueError("Symlinks are not supported: " + name)
    if not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Path outside project: " + name)
    return path

def read_file(root, name):
    p = safe_path(root, name)
    if not p.exists():
        return None
    if not p.is_file():
        raise ValueError("Not a normal file: " + name)
    return p.read_bytes()

def verify(root):
    originals = {}
    for name, expected in PREREQUISITES.items():
        data = read_file(root, name)
        if data is None or digest(data) != expected:
            raise ValueError("Required file missing or different: " + name + "; nothing changed. Ask for help.")
    for name, old in EXPECTED.items():
        data = read_file(root, name)
        current = None if data is None else digest(data)
        if current not in (old, NEW[name]):
            raise ValueError("Local file is different: " + name + "; nothing changed. Ask for help.")
        originals[name] = data
    return originals

def main():
    root = Path.cwd()
    if not (root / "manage.py").is_file() or not (root / "mysite" / "settings.py").is_file():
        raise ValueError("Open PowerShell in your project folder first. Nothing changed.")
    data = json.loads(zlib.decompress(base64.b85decode(PAYLOAD)).decode("utf-8"))
    decoded = {name: base64.b64decode(value, validate=True) for name, value in data.items()}
    if set(decoded) != set(EXPECTED) or any(digest(decoded[k]) != NEW[k] for k in decoded):
        raise ValueError("Installer verification failed. Nothing changed.")
    originals = verify(root)
    changes = [name for name, original in originals.items() if original is None or digest(original) != NEW[name]]
    if not changes:
        print("The combined All Places update is already installed. Nothing changed.")
        return
    print("Compatibility checks passed for", len(EXPECTED), "update files and", len(PREREQUISITES), "prerequisites.")
    print("This updates code only. No database, media, migrations or account data will be changed.")
    print("The inline carousel sort is preserved; the old Nearby URL redirects to All Places.")
    if input("Type APPLY PLACES to install, or press Enter to cancel: ").strip() != "APPLY PLACES":
        print("Cancelled. Nothing changed.")
        return
    # Recheck after the confirmation to detect edits made while waiting.
    again = verify(root)
    if again != originals:
        raise ValueError("A file changed during confirmation. Nothing changed; try again after review.")
    backup = Path.home() / ("EK_code_backup_combined_places_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
    backup.mkdir(parents=False, exist_ok=False)
    for name in changes:
        if originals[name] is not None:
            dest = backup / name
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_bytes(originals[name])
    updated = []
    try:
        for name in changes:
            path = safe_path(root, name)
            path.parent.mkdir(parents=True, exist_ok=True)
            fd, temp = tempfile.mkstemp(prefix=".ek-", dir=str(path.parent))
            try:
                with os.fdopen(fd, "wb") as handle:
                    handle.write(decoded[name])
                os.replace(temp, path)
            finally:
                if os.path.exists(temp):
                    os.unlink(temp)
            updated.append(name)
            print("Updated:", name)
    except Exception:
        for name in reversed(updated):
            path = safe_path(root, name)
            if originals[name] is None:
                path.unlink(missing_ok=True)
            else:
                path.write_bytes(originals[name])
            print("Rolled back:", name)
        raise
    print("Code backup:", backup)
    print("Finished. Database, media and migrations were not changed.")
    print("Restart Django and test All Places. Some old Nearby-page tests still need updating.")

if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, EOFError) as exc:
        print("STOP:", exc, file=sys.stderr)
        sys.exit(1)
